def construct_balanced_sequences(n, s):
    if s.count('1') % 2 != 0:
        return "NO", "", ""

    a = []
    b = []
    balance_a = 0
    balance_b = 0

    for i in range(n):
        if s[i] == '1':
            if balance_a <= balance_b:
                a.append('(')
                b.append('(')
                balance_a += 1
                balance_b += 1
            else:
                a.append(')')
                b.append(')')
                balance_a -= 1
                balance_b -= 1
        else:
            if balance_a > balance_b:
                a.append('(')
                b.append(')')
                balance_a += 1
                balance_b -= 1
            else:
                a.append(')')
                b.append('(')
                balance_a -= 1
                balance_b += 1

    return "YES", ''.join(a), ''.join(b)

def main():
    t = int(input())
    results = []
    for _ in range(t):
        n = int(input())
        s = input()
        result, a, b = construct_balanced_sequences(n, s)
        results.append((result, a, b))

    for result, a, b in results:
        print(result)
        if result == "YES":
            print(a)
            print(b)

main()
